-- ==== 10/16: 105-goals.rollback.sql (verbatim) ====
-- 105-goals.rollback.sql (KpopCards lots 3 + 4 + 5): undo of 105-goals.sql.
--
-- What:   drops the 5 functions of 105, the 4 tables cards_sets_claimed, cards_week_claims, cards_idem and cards_audit, and puts
--         cards_wallets_stock_check back to stock between 0 and 5.
-- Why:    without 105 there are no sets, no weekly list and no idempotency ledger; 110 and later files need them, so undo those first.
-- Rows:   4 tables dropped with their rows. Refused while a set or a week is claimed, while a ledger row or an audit row exists (they are the only
--         record of what was paid and spent), or while a stack holds more than 5 packs (the old check would refuse it).
-- Verify: select count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname in ('cards_goals_progress', 'cards_week_progress', 'cards_missions', 'cards_claim', 'cards_idem_gc');   expect 0
-- Verify: select pg_get_constraintdef(oid) like '%500%' from pg_constraint where conname = 'cards_wallets_stock_check' and conrelid = 'public.cards_wallets'::regclass;   expect f
-- Undo:   run 105-goals.sql again.
-- o1-transaction: single, ONE DO block. Idempotent: a second run changes nothing.

do $c105r$
begin
  perform set_config('lock_timeout', '5s', true);
  perform set_config('client_min_messages', 'warning', true);

  if to_regclass('public.cards_sets_claimed') is not null and exists (select 1 from public.cards_sets_claimed) then
    raise exception '105-goals rollback: refused, a set is claimed (cards_sets_claimed holds rows)';
  end if;
  if to_regclass('public.cards_week_claims') is not null and exists (select 1 from public.cards_week_claims) then
    raise exception '105-goals rollback: refused, a week is claimed (cards_week_claims holds rows)';
  end if;
  if to_regclass('public.cards_idem') is not null and exists (select 1 from public.cards_idem) then
    raise exception '105-goals rollback: refused, the idempotency ledger holds rows';
  end if;
  if to_regclass('public.cards_audit') is not null and exists (select 1 from public.cards_audit) then
    raise exception '105-goals rollback: refused, the audit trail holds rows';
  end if;
  if exists (select 1 from public.cards_wallets where stock > 5) then
    raise exception '105-goals rollback: refused, a stack holds more than 5 packs';
  end if;

  drop function if exists public.cards_claim(uuid, text, text, timestamptz, integer);
  drop function if exists public.cards_missions(uuid, timestamptz);
  drop function if exists public.cards_week_progress(uuid, timestamptz);
  drop function if exists public.cards_goals_progress(uuid, integer[]);
  drop function if exists public.cards_idem_gc(timestamptz);
  drop table if exists public.cards_sets_claimed;
  drop table if exists public.cards_week_claims;
  drop table if exists public.cards_idem;
  drop table if exists public.cards_audit;

  if exists (select 1 from pg_constraint where conname = 'cards_wallets_stock_check' and conrelid = 'public.cards_wallets'::regclass
              and pg_get_constraintdef(oid) like '%500%') then
    alter table public.cards_wallets drop constraint cards_wallets_stock_check;
    alter table public.cards_wallets add constraint cards_wallets_stock_check check (stock between 0 and 5);
  end if;

  notify pgrst, 'reload schema';
end $c105r$;

-- ==== 11/16: 104-economy.rollback.sql (verbatim) ====
-- 104-economy.rollback.sql (Bunnyverse Cards lots 3 and 4, lane ECON): undo of 104-economy.sql.
--
-- What:   restores cards_roll, cards_wallet and cards_apply_pack exactly as 002-functions.sql defines them (the 104 versions are dropped
--         first, so exactly one of each name exists), drops the 7 functions 104 added, the 2 tables cards_crafts and cards_wishlist and the
--         5 columns cards_wallets.timer_today, cards_packs.focus, cards_packs.new_count, cards_owned.first_pack_no, cards_owned.first_source.
-- Why:    without 104 the Gold guarantee, the timer cap, crafting, the wishlist, the focus pack, the ad shards and the moment are gone; the
--         routes of lots 3 and 4 then answer a server error, so switch NET_CARDS off or deploy the code of lot 2 first.
-- Rows:   2 tables dropped (their rows with them: the wishlists), 5 columns dropped (the day's timer count, the focus marks, the moment data).
--         Refused while a craft is recorded (the ledger is the only record of the shards spent; the crafted cards stay in the binders).
--         The shards an ad gave stay in the wallets. No other data is changed.
-- Verify: select count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname in ('cards_pity_count', 'cards_pity_pool', 'cards_focus_used', 'cards_craft', 'cards_wish', 'cards_ad_grant', 'cards_recent_packs');   expect 0
-- Verify: select proname, count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname in ('cards_roll', 'cards_wallet', 'cards_apply_pack') group by proname order by proname;   expect cards_apply_pack 1, cards_roll 1, cards_wallet 1
-- Verify: select (public.cards_wallet('00000000-0000-0000-0000-000000000000', '2026-11-12 10:00+00')) ->> 'timer_left';   expect empty (the key is gone)
-- Undo:   run 104-economy.sql again.
-- o1-transaction: single, ONE DO block. Idempotent: a second run changes nothing.

do $c104r$
begin
  perform set_config('lock_timeout', '5s', true);
  perform set_config('client_min_messages', 'warning', true);

  if to_regclass('public.cards_crafts') is not null then
    if exists (select 1 from public.cards_crafts) then
      raise exception '104-economy rollback: refused, a craft is recorded (cards_crafts holds rows)';
    end if;
  end if;

  -- The 104 functions out, the 002 ones back.
  drop function if exists public.cards_wallet(uuid, timestamptz, integer, integer, integer);
  drop function if exists public.cards_apply_pack(uuid, text, integer[], uuid, timestamptz, integer, integer, integer, text);
  drop function if exists public.cards_roll(integer, timestamptz, date, integer, integer, timestamptz, integer, integer);
  drop function if exists public.cards_wallet(uuid, timestamptz, integer, integer);
  drop function if exists public.cards_apply_pack(uuid, text, integer[], uuid, timestamptz, integer, integer);
  drop function if exists public.cards_roll(integer, timestamptz, date, integer, integer, timestamptz);

  create or replace function public.cards_roll(p_stock integer, p_anchor timestamptz, p_day date, p_ads integer, p_bonus integer, p_now timestamptz)
    returns jsonb
    language plpgsql stable set search_path = public
    as $f$
  declare
    v_today date := (p_now at time zone 'Europe/Paris')::date;
    v_stock integer := p_stock;
    v_anchor timestamptz := p_anchor;
    v_ads integer := p_ads;
    v_bonus integer := p_bonus;
    k bigint;
  begin
    if p_day is distinct from v_today then
      v_ads := 0;
      v_bonus := 0;
      if v_stock < 5 then
        v_stock := 5;
        v_anchor := p_now;
      end if;
    end if;
    if v_stock >= 5 then
      v_anchor := p_now;
    else
      k := floor(extract(epoch from (p_now - v_anchor)) / 600);
      if k > 0 then
        v_stock := least(5, v_stock + k);
        v_anchor := v_anchor + make_interval(secs => (k * 600)::double precision);
        if v_stock >= 5 then
          v_anchor := p_now;
        end if;
      end if;
    end if;
    return jsonb_build_object('stock', v_stock, 'anchor', v_anchor, 'paris_day', v_today, 'ads_today', v_ads, 'bonus_today', v_bonus);
  end
  $f$;

  create or replace function public.cards_wallet(p_user uuid, p_now timestamptz default now(), p_ads_limit integer default 10, p_bonus_cap integer default 3)
    returns jsonb
    language plpgsql stable security definer set search_path = public
    as $f$
  declare
    w public.cards_wallets%rowtype;
    v_today date := (p_now at time zone 'Europe/Paris')::date;
    r jsonb;
    v_stock integer;
    v_anchor timestamptz;
    v_bonus_seen integer;
  begin
    select * into w from public.cards_wallets where user_id = p_user;
    if not found then
      w.stock := 5; w.anchor := p_now; w.paris_day := v_today; w.ads_today := 0; w.bonus_today := 0; w.shards := 0;
    end if;
    r := public.cards_roll(w.stock, w.anchor, w.paris_day, w.ads_today, w.bonus_today, p_now);
    v_stock := (r ->> 'stock')::integer;
    v_anchor := (r ->> 'anchor')::timestamptz;
    v_bonus_seen := case when p_bonus_cap <= 0 then 0 else public.cards_bonus_plays(p_user, v_today) end;
    return jsonb_build_object(
      'stock', v_stock,
      'anchor', v_anchor,
      'paris_day', v_today,
      'ads_today', (r ->> 'ads_today')::integer,
      'bonus_today', (r ->> 'bonus_today')::integer,
      'shards', w.shards,
      'ads_left', greatest(0, p_ads_limit - (r ->> 'ads_today')::integer),
      'bonus_left', greatest(0, least(p_bonus_cap, v_bonus_seen) - (r ->> 'bonus_today')::integer),
      'next_at', case when v_stock >= 5 then null else v_anchor + interval '600 seconds' end,
      'midnight_at', ((v_today + 1)::timestamp at time zone 'Europe/Paris'));
  end
  $f$;

  create or replace function public.cards_apply_pack(
      p_user uuid, p_source text, p_cards integer[], p_ticket uuid default null, p_now timestamptz default now(),
      p_ads_limit integer default 10, p_bonus_cap integer default 3)
    returns jsonb
    language plpgsql security definer set search_path = public
    as $f$
  declare
    w public.cards_wallets%rowtype;
    v_today date := (p_now at time zone 'Europe/Paris')::date;
    r jsonb;
    v_stock integer;
    v_anchor timestamptz;
    v_ads integer;
    v_bonus integer;
    v_shards integer;
    v_ok integer;
    v_want integer;
    v_fifth text;
    v_t uuid;
    v_card integer;
    v_new boolean;
    v_out jsonb := '[]'::jsonb;
    v_seen integer[] := '{}';
    v_pack uuid;
  begin
    if p_user is null then raise exception 'cards: user'; end if;
    if p_source is null or p_source not in ('stock', 'ad', 'shards', 'bonus') then raise exception 'cards: source'; end if;
    if p_cards is null or cardinality(p_cards) <> 5 or array_position(p_cards, null) is not null then raise exception 'cards: pack'; end if;

    select count(distinct c.card_no) into v_ok
      from public.cards_catalog c join public.cards_entities e on e.id = c.entity_id
     where c.card_no = any (p_cards) and c.in_packs and e.active;
    select count(distinct x) into v_want from unnest(p_cards) as x;
    if v_ok <> v_want then raise exception 'cards: pack'; end if;
    select rarity into v_fifth from public.cards_catalog where card_no = p_cards[5];
    if v_fifth = 'C' then raise exception 'cards: pack'; end if;

    insert into public.cards_wallets (user_id, stock, anchor, paris_day, ads_today, bonus_today, shards, version, updated_at)
    values (p_user, 5, p_now, v_today, 0, 0, 0, 0, p_now)
    on conflict (user_id) do nothing;
    select * into w from public.cards_wallets where user_id = p_user for update;

    r := public.cards_roll(w.stock, w.anchor, w.paris_day, w.ads_today, w.bonus_today, p_now);
    v_stock := (r ->> 'stock')::integer;
    v_anchor := (r ->> 'anchor')::timestamptz;
    v_ads := (r ->> 'ads_today')::integer;
    v_bonus := (r ->> 'bonus_today')::integer;
    v_shards := w.shards;

    if p_source = 'stock' then
      if v_stock < 1 then raise exception 'cards: empty'; end if;
      v_stock := v_stock - 1;
    elsif p_source = 'ad' then
      if v_ads >= p_ads_limit then raise exception 'cards: ad_limit'; end if;
      -- Review 1 finding 9: only a ticket issued at least 10 seconds and at most 1 hour before (no rewarded ad is shorter; an older ticket
      -- is dropped). A ticket refused for its age is not spent. Google's rewarded event itself cannot be checked on the server.
      update public.cards_ad_tickets set used_at = p_now
       where id = p_ticket and user_id = p_user and used_at is null
         and issued_at <= p_now - interval '10 seconds' and issued_at >= p_now - interval '1 hour'
      returning id into v_t;
      if v_t is null then raise exception 'cards: ticket'; end if;
      v_ads := v_ads + 1;
    elsif p_source = 'shards' then
      if v_shards < 50 then raise exception 'cards: shards'; end if;
      v_shards := v_shards - 50;
    else
      if p_bonus_cap <= 0 or v_bonus >= least(p_bonus_cap, public.cards_bonus_plays(p_user, v_today)) then raise exception 'cards: bonus'; end if;
      v_bonus := v_bonus + 1;
    end if;

    foreach v_card in array p_cards loop
      v_new := not (v_card = any (v_seen)) and not exists (select 1 from public.cards_owned o where o.user_id = p_user and o.card_no = v_card);
      v_seen := v_seen || v_card;
      insert into public.cards_owned as o (user_id, card_no, copies, first_at, last_at)
      values (p_user, v_card, 1, p_now, p_now)
      on conflict (user_id, card_no) do update set copies = o.copies + 1, last_at = p_now;
      v_out := v_out || jsonb_build_array(jsonb_build_object('n', v_card, 'isNew', v_new));
    end loop;

    insert into public.cards_packs (user_id, source, cards, opened_at) values (p_user, p_source, p_cards, p_now) returning id into v_pack;

    update public.cards_wallets
       set stock = v_stock, anchor = v_anchor, paris_day = v_today, ads_today = v_ads, bonus_today = v_bonus,
           shards = v_shards, version = version + 1, updated_at = p_now
     where user_id = p_user;

    return jsonb_build_object('id', v_pack, 'source', p_source, 'cards', v_out);
  end
  $f$;

  revoke all on function public.cards_wallet(uuid, timestamptz, integer, integer) from public, anon, authenticated;
  revoke all on function public.cards_apply_pack(uuid, text, integer[], uuid, timestamptz, integer, integer) from public, anon, authenticated;
  revoke all on function public.cards_roll(integer, timestamptz, date, integer, integer, timestamptz) from public, anon, authenticated;
  grant execute on function public.cards_wallet(uuid, timestamptz, integer, integer) to service_role;
  grant execute on function public.cards_apply_pack(uuid, text, integer[], uuid, timestamptz, integer, integer) to service_role;
  grant execute on function public.cards_roll(integer, timestamptz, date, integer, integer, timestamptz) to service_role;

  drop function if exists public.cards_recent_packs(uuid, integer);
  drop function if exists public.cards_ad_grant(uuid, uuid, timestamptz, integer, integer, integer);
  drop function if exists public.cards_wish(uuid, integer, boolean, timestamptz);
  drop function if exists public.cards_craft(uuid, integer, timestamptz);
  drop function if exists public.cards_focus_used(uuid, timestamptz);
  drop function if exists public.cards_pity_pool();
  drop function if exists public.cards_pity_count(uuid);

  drop table if exists public.cards_wishlist;
  drop table if exists public.cards_crafts;
  drop index if exists public.cards_packs_focus_idx;
  alter table public.cards_packs drop constraint if exists cards_packs_focus_fkey;
  alter table public.cards_packs drop constraint if exists cards_packs_new_count_check;
  alter table public.cards_packs drop column if exists focus;
  alter table public.cards_packs drop column if exists new_count;
  alter table public.cards_owned drop constraint if exists cards_owned_first_pack_no_check;
  alter table public.cards_owned drop constraint if exists cards_owned_first_source_check;
  alter table public.cards_owned drop column if exists first_pack_no;
  alter table public.cards_owned drop column if exists first_source;
  alter table public.cards_wallets drop constraint if exists cards_wallets_timer_today_check;
  alter table public.cards_wallets drop column if exists timer_today;

  notify pgrst, 'reload schema';
end $c104r$;

-- ==== 12/16: 103-catalog-photos.rollback.sql (verbatim) ====
-- 103-catalog-photos.rollback.sql (undo of 103-catalog-photos.sql)
--
-- What:   empties cards_catalog, cards_photos and cards_entities, drops cards_build_catalog(), cards_photo_ready() and its trigger, and gives
--         cards_photos back the shape of 102 (no sha1, quality, stage, event_date_precision, news_only; slot 1 to 3). The catalog stays
--         EMPTY: apply 102-catalog-rebuild.sql again to get the one-photo catalog of lot 2 back.
-- Refuses: while a player owns a card (cards_owned) or has opened a pack (cards_packs).
-- Verify: select count(*) from public.cards_catalog;   expect 0
-- Verify: select count(*) from pg_proc where proname in ('cards_build_catalog', 'cards_photo_ready');   expect 0
-- Verify: select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'cards_photos' and column_name in ('sha1', 'quality', 'stage', 'event_date_precision', 'news_only');   expect 0
-- o1-transaction: single, ONE DO block. Idempotent.

do $c103r$
begin
  perform set_config('lock_timeout', '5s', true);
  perform set_config('client_min_messages', 'warning', true);

  if to_regclass('public.cards_catalog') is null then
    return;
  end if;
  if exists (select 1 from public.cards_owned) then
    raise exception '103-catalog-photos rollback: a player owns a card';
  end if;
  if exists (select 1 from public.cards_packs) then
    raise exception '103-catalog-photos rollback: a pack was opened';
  end if;

  delete from public.cards_catalog;
  delete from public.cards_photos;
  delete from public.cards_entities;

  drop trigger if exists cards_photos_ready on public.cards_photos;
  drop function if exists public.cards_photo_ready();
  drop function if exists public.cards_build_catalog();
  alter table public.cards_photos drop constraint if exists cards_photos_quality_check;
  alter table public.cards_photos drop constraint if exists cards_photos_event_date_precision_check;
  alter table public.cards_photos drop column if exists sha1;
  alter table public.cards_photos drop column if exists quality;
  alter table public.cards_photos drop column if exists stage;
  alter table public.cards_photos drop column if exists event_date_precision;
  alter table public.cards_photos drop column if exists news_only;
  alter table public.cards_photos drop constraint if exists cards_photos_slot_check;
  alter table public.cards_photos add constraint cards_photos_slot_check check (slot between 1 and 3);
end $c103r$;

-- ==== 13/16: 099b-idols-returning.rollback.sql (verbatim) ====
-- 099b-idols-returning.rollback.sql (undo of 099b-idols-returning.sql)
--
-- What:   deletes the public.idols rows 099b can have inserted: same group slug, same name, same wikidata_qid, and a review_reason starting
--         with '099b-idols-returning' (all four must match, so a row that existed before 099b is never touched).
-- Refuses: while a player owns a card of one of these groups, or has opened a pack.
-- Verify: select count(*) from public.idols where review_reason like '099b-idols-returning%';   expect 0
-- o1-transaction: single, ONE DO block. Idempotent.

do $i099br$
declare
  v_data constant jsonb := $members$[
  {"slug":"fromis-9","members":[{"name":"Song Ha-young","qid":"Q58816368","ord":1,"birth_date":"1997-09-29"},{"name":"Park Ji-won","qid":"Q56695886","ord":2,"birth_date":"1998-03-20"},{"name":"Lee Chae-young","qid":"Q56660258","ord":3,"birth_date":"2000-05-14"},{"name":"Lee Na-gyung","qid":"Q56660245","ord":4,"birth_date":"2000-06-01"},{"name":"Baek Ji-heon","qid":"Q56660176","ord":5,"birth_date":"2003-04-17"}]},
  {"slug":"kara","members":[{"name":"Gyuri","qid":"Q495000","ord":1,"birth_date":"1988-05-21"},{"name":"Seungyeon","qid":"Q495020","ord":2,"birth_date":"1988-07-24"},{"name":"Nicole","qid":"Q494992","ord":3,"birth_date":"1991-10-07"},{"name":"Jiyoung","qid":"Q495009","ord":4,"birth_date":"1994-01-18"},{"name":"Youngji","qid":"Q17302045","ord":5,"birth_date":"1994-08-30"}]},
  {"slug":"loona","members":[{"name":"Heejin","qid":"Q56259179","ord":1,"birth_date":"2000-10-19"},{"name":"Hyunjin","qid":"Q48893612","ord":2,"birth_date":"2000-11-15"},{"name":"Haseul","qid":"Q57318729","ord":3,"birth_date":"1997-08-18"},{"name":"Yeojin","qid":"Q56824821","ord":4,"birth_date":"2002-11-11"},{"name":"Kim Lip","qid":"Q56816418","ord":5,"birth_date":"1999-02-10"},{"name":"Jinsoul","qid":"Q56825122","ord":6,"birth_date":"1997-06-13"},{"name":"Choerry","qid":"Q58224261","ord":7,"birth_date":"2001-06-04"},{"name":"Yves","qid":"Q58825704","ord":8,"birth_date":"1997-05-24"},{"name":"Olivia Hye","qid":"Q58825825","ord":9,"birth_date":"2001-11-13"},{"name":"Vivi","qid":"Q57317398","ord":10,"birth_date":"1996-12-09"},{"name":"Go Won","qid":"Q58825794","ord":11,"birth_date":"2000-11-19"}]}
]$members$;
  v_deleted int;
begin
  perform set_config('lock_timeout', '5s', true);
  if to_regclass('public.idols') is null then
    return;
  end if;
  -- nested: PL/pgSQL plans a condition whole, so a table is named only once it is known to exist
  if to_regclass('public.cards_owned') is not null and to_regclass('public.cards_catalog') is not null then
    if exists (select 1 from public.cards_owned o join public.cards_catalog c on c.card_no = o.card_no
                where c.entity_id in (select 'group:' || x from unnest(array['fromis-9', 'kara', 'loona']) x)) then
      raise exception '099b-idols-returning rollback: a player owns a card of one of these groups';
    end if;
  end if;
  if to_regclass('public.cards_packs') is not null then
    if exists (select 1 from public.cards_packs) then
      raise exception '099b-idols-returning rollback: a pack was opened';
    end if;
  end if;
  delete from public.idols i
   using public.groups g, jsonb_array_elements(v_data) s, jsonb_array_elements(s.value->'members') m
   where g.id = i.group_id and g.slug = s.value->>'slug' and i.name = m.value->>'name' and i.wikidata_qid = m.value->>'qid'
     and i.review_reason like '099b-idols-returning%';
  get diagnostics v_deleted = row_count;
  raise notice '099b-idols-returning rollback: % rows deleted', v_deleted;
end $i099br$;

-- ==== 14/16: 102-catalog-rebuild.rollback.sql (verbatim) ====
-- 102-catalog-rebuild.rollback.sql (undo of 102-catalog-rebuild.sql)
--
-- What:   empties cards_catalog, cards_photos and cards_entities, then gives them back the shape of 001: drops part, small_2x and end_year,
--         and the unique key (entity_id, rarity, part) returns to (entity_id, rarity). The catalog stays EMPTY: 101 is not re-run here,
--         because 101 predates the age rule of lot 2 (it would bring back the subjects that rule leaves out). Apply 102 again to refill it.
-- Refuses: while a player owns a card (cards_owned) or has opened a pack (cards_packs).
-- Verify: select count(*) from public.cards_catalog;   expect 0
-- Verify: select count(*) from information_schema.columns where table_schema = 'public' and table_name in ('cards_catalog', 'cards_entities') and column_name in ('part', 'small_2x', 'end_year');   expect 0
-- o1-transaction: single, ONE DO block. Idempotent.

do $c102r$
begin
  perform set_config('lock_timeout', '5s', true);
  perform set_config('client_min_messages', 'warning', true);

  if to_regclass('public.cards_catalog') is null then
    return;
  end if;
  if exists (select 1 from public.cards_owned) then
    raise exception '102-catalog-rebuild rollback: a player owns a card';
  end if;
  if exists (select 1 from public.cards_packs) then
    raise exception '102-catalog-rebuild rollback: a pack was opened';
  end if;

  delete from public.cards_catalog;
  delete from public.cards_photos;
  delete from public.cards_entities;

  alter table public.cards_catalog drop constraint if exists cards_catalog_entity_rarity_part_key;
  alter table public.cards_catalog drop constraint if exists cards_catalog_part_check;
  alter table public.cards_catalog drop column if exists part;
  alter table public.cards_catalog drop column if exists small_2x;
  alter table public.cards_entities drop constraint if exists cards_entities_end_year_check;
  alter table public.cards_entities drop column if exists end_year;
  if not exists (select 1 from pg_constraint where conname = 'cards_catalog_entity_rarity_key' and conrelid = 'public.cards_catalog'::regclass) then
    alter table public.cards_catalog add constraint cards_catalog_entity_rarity_key unique (entity_id, rarity);
  end if;
end $c102r$;

